function fq(e, t) {
  const a = { universos: [], calculo: [], decisiones: [], limites: [] };
  for (const i of e) {
    const s = i.startsWith("NC:") ? "nc" : "sni";
    a.universos.includes(s) || a.universos.push(s);
    const c = dq[String(t(i) ?? "").replace(/^[A-Z][0-9]{2}b?_/i, "")];
    if (c) for (const u of ["calculo", "decisiones", "limites"]) for (const f of c[u]) a[u].includes(f) || a[u].push(f);
  }
  return a.calculo.length ? a : null;
}
